import{_ as a,o as d,c as e,a5 as r}from"./chunks/framework.BMR-TWOq.js";const h="/RBQ/nightly/images/operation/status-lights.ko.svg",u=JSON.parse('{"title":"상태 표시등","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/operation/status-lights.md","filePath":"ko/manual/operation/status-lights.md","lastUpdated":1793984559000}'),o={name:"ko/manual/operation/status-lights.md"};function n(i,t,l,s,b,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="상태-표시등" tabindex="-1">상태 표시등 <a class="header-anchor" href="#상태-표시등" aria-label="Permalink to &quot;상태 표시등&quot;">​</a></h1><p>상단 패널의 표시등을 보면 조종기가 없어도 로봇 상태를 바로 알 수 있습니다. 윗줄 4칸은 배터리 잔량(1)이고, 아랫줄은 왼쪽부터 E-STOP(2), 통신모듈(3), 제어 모드(4), 네트워크(5)입니다.</p><figure><img style="max-width:100%;width:min(480px, 100%);height:auto;display:block;margin:1rem auto;" src="'+h+'" alt="상단 패널 표시등: 1 배터리 잔량(윗줄 4칸), 아랫줄 왼쪽부터 2 E-STOP, 3 통신모듈, 4 제어 모드, 5 네트워크"><figcaption style="text-align:center;">[ 상단 패널 표시등 (개략도) ]</figcaption></figure><table tabindex="0"><thead><tr><th>번호</th><th>표시등</th><th>보여 주는 것</th></tr></thead><tbody><tr><td>1</td><td>배터리 (4칸)</td><td>남은 잔량, 충전, 배터리 이상</td></tr><tr><td>2</td><td>E-STOP</td><td>비상 정지 상태인지</td></tr><tr><td>3</td><td>통신모듈</td><td>로봇 PC가 통신모듈과 연결되는지</td></tr><tr><td>4</td><td>제어 모드</td><td>누가 로봇을 조종하는지, 도킹 중인지</td></tr><tr><td>5</td><td>네트워크</td><td>U-PC와 R-PC 네트워크의 데이터</td></tr></tbody></table><p>전원을 켜고 10초 동안은 네트워크 표시등을 뺀 모든 표시등이 꺼져 있습니다.</p><h2 id="battery" tabindex="-1">배터리 <a class="header-anchor" href="#battery" aria-label="Permalink to &quot;배터리 {#battery}&quot;">​</a></h2><p>4칸은 배터리 팩 두 개를 합친 남은 잔량을 보여 줍니다. 한 칸이 25 %이고, 그 칸의 몫이 조금이라도 남아 있으면 켜집니다. 잔량이 60 %이면 3칸이 켜집니다.</p><table tabindex="0"><thead><tr><th>표시</th><th>뜻</th><th>할 일</th></tr></thead><tbody><tr><td>초록 켜짐</td><td>정상. 켜진 칸 수가 남은 잔량입니다</td><td>—</td></tr><tr><td>빨강 켜짐</td><td>팩 하나를 쓸 수 없습니다. 팩이 인식되지 않거나, 두 팩이 전류를 고르게 나눠 내지 않습니다. 인식되지 않은 팩은 잔량에서 빠지므로 최대 2칸까지만 켜집니다</td><td>앱에서 배터리 팩을 확인합니다</td></tr><tr><td>주황 1칸 빠른 점멸</td><td>10 % 이하입니다. 곧 전원이 꺼집니다</td><td>바로 충전합니다</td></tr><tr><td>4칸 모두 빨강 빠른 점멸</td><td>배터리 보호가 동작했습니다. 과전압, 저전압, 과전류, 단락, 과열 중 하나입니다</td><td>로봇을 멈추고 앱에서 배터리를 확인합니다</td></tr><tr><td>모두 꺼짐</td><td>배터리 정보가 들어오지 않습니다</td><td>앱에서 배터리를 확인합니다</td></tr></tbody></table><h3 id="battery-charging" tabindex="-1">충전 중 <a class="header-anchor" href="#battery-charging" aria-label="Permalink to &quot;충전 중 {#battery-charging}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>표시</th><th>뜻</th></tr></thead><tbody><tr><td>켜진 칸 중 마지막 칸이 느린 점멸</td><td>충전 중입니다</td></tr><tr><td>켜진 칸 모두 켜짐</td><td>충전이 끝났거나(99 % 이상), 다 차서 충전이 멈췄습니다</td></tr><tr><td>켜진 칸 중 마지막 칸이 빨강 빠른 점멸</td><td>충전 이상입니다. 잔량이 90 % 미만인데 충전 전류가 60초 동안 0.2 A 아래에 머물렀습니다. 충전기나 도킹 스테이션 연결을 확인합니다</td></tr></tbody></table><h3 id="battery-health" tabindex="-1">켤 때 배터리 수명 알림 <a class="header-anchor" href="#battery-health" aria-label="Permalink to &quot;켤 때 배터리 수명 알림 {#battery-health}&quot;">​</a></h3><p>팩 하나라도 수명(SOH)이 80 % 아래이면, 전원을 켜고 10초부터 30초까지 4칸이 모두 주황으로 켜집니다. 팩은 계속 쓸 수 있지만 노후된 상태이니 교체를 준비합니다.</p><h2 id="status" tabindex="-1">상태 표시등 <a class="header-anchor" href="#status" aria-label="Permalink to &quot;상태 표시등 {#status}&quot;">​</a></h2><p>상태 표시등은 칸마다 한 가지만 보여 줍니다. 초록이면 정상입니다.</p><table tabindex="0"><thead><tr><th>표시등</th><th>초록 켜짐</th><th>그 밖</th></tr></thead><tbody><tr><td>E-STOP</td><td>정상</td><td><strong>빨강 켜짐</strong> — 비상 정지 상태입니다. 비상 정지 버튼, 앱의 <code>E-STOP</code>, 넘어짐, 치명적인 고장 중 하나입니다. 복구는 <a href="/RBQ/nightly/ko/manual/operation/emo.html">비상 정지 및 복구</a>를 봅니다</td></tr><tr><td>통신모듈</td><td>로봇 PC가 통신모듈과 연결됩니다</td><td><strong>빨강 켜짐</strong> — 로봇 PC가 통신모듈과 연결되지 않습니다. 통신모듈의 전원과 케이블을 확인합니다</td></tr><tr><td>제어 모드</td><td>조종기 모드</td><td><strong>파랑 켜짐</strong> — 외부 조종(SLAM·SDK)이 로봇을 움직이는 중입니다. <strong>느린 점멸</strong> — 도킹 중이며, 색은 지금 모드를 따릅니다</td></tr></tbody></table><h3 id="pc" tabindex="-1">로봇 PC가 켜지는 중이거나 응답이 없을 때 <a class="header-anchor" href="#pc" aria-label="Permalink to &quot;로봇 PC가 켜지는 중이거나 응답이 없을 때 {#pc}&quot;">​</a></h3><p>로봇 PC가 꺼져 있으면 패널이 상태 표시등 3개를 넘겨받아 표시합니다.</p><table tabindex="0"><thead><tr><th>표시</th><th>뜻</th><th>할 일</th></tr></thead><tbody><tr><td>흰색이 세 칸을 차례로 흐름</td><td>로봇 PC가 켜지는 중입니다</td><td>기다립니다. 소프트웨어를 다시 시작할 때도 잠깐 나옵니다</td></tr><tr><td>세 칸 모두 빨강 빠른 점멸</td><td>로봇 PC가 응답하지 않습니다. 멈췄거나 2분 안에 켜지지 않았습니다</td><td>로봇을 다시 시작합니다</td></tr></tbody></table><h3 id="lamp-test" tabindex="-1">램프 테스트 <a class="header-anchor" href="#lamp-test" aria-label="Permalink to &quot;램프 테스트 {#lamp-test}&quot;">​</a></h3><p>로봇 소프트웨어가 시작될 때와 앱에서 <code>램프 테스트</code>를 누를 때(<a href="/RBQ/nightly/ko/manual/gui/maintenance.html#led-bottom">정비</a>), 배터리 표시등과 상태 표시등이 1.6초 동안 빨강 → 초록 → 파랑으로 켜집니다. 모든 표시등이 켜지는지 확인할 때 씁니다.</p><h2 id="network" tabindex="-1">네트워크 표시등 <a class="header-anchor" href="#network" aria-label="Permalink to &quot;네트워크 표시등 {#network}&quot;">​</a></h2><p>네트워크 표시등에는 작은 표시등 두 개가 들어 있습니다. 빨강은 U-PC(사용자 PC)로 데이터가 오갈 때, 파랑은 R-PC(로봇 PC)로 데이터가 오갈 때 깜빡입니다. 하드웨어가 직접 켜는 표시등이라 끌 수 없습니다. 네트워크 구성은 <a href="/RBQ/nightly/ko/manual/interface/network.html">네트워크</a>를 봅니다.</p>',22)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
